<?php
require_once 'config.php';requirePost();$user=requireRole('admin','supervisor','expert');if($user['role']!=='expert'&&!hasPermission('can_chat'))jsonResponse(['success'=>false,'message'=>'دسترسی چت غیرفعال است.'],403);$title=normalizeText((string)($_POST['title']??''),100);if($title==='')$title='گروه جدید';$raw=$_POST['members']??'[]';$members=json_decode((string)$raw,true);if(!is_array($members))$members=[];$allowed=[];foreach(allChatUsers($pdo,$user) as $c)$allowed[$c['role'].'|'.$c['username']]=$c;$allowed[$user['role'].'|'.$user['username']]=['username'=>$user['username'],'role'=>$user['role'],'display_name'=>$user['display_name']];$members[]= ['username'=>$user['username'],'role'=>$user['role']];$clean=[];foreach($members as $m){if(!is_array($m))continue;$k=($m['role']??'').'|'.($m['username']??'');if(isset($allowed[$k]))$clean[$k]=$allowed[$k];}if(count($clean)<2)jsonResponse(['success'=>false,'message'=>'حداقل یک عضو دیگر انتخاب کنید.'],400);
$pdo->beginTransaction();try{$st=$pdo->prepare("INSERT INTO chat_conversations(type,title,created_by,created_by_role) VALUES('group',?,?,?)");$st->execute([$title,$user['username'],$user['role']]);$id=(int)$pdo->lastInsertId();$st=$pdo->prepare("INSERT INTO chat_members(conversation_id,username,role,display_name) VALUES(?,?,?,?)");foreach($clean as $m)$st->execute([$id,$m['username'],$m['role'],$m['display_name']]);$pdo->commit();jsonResponse(['success'=>true,'conversation_id'=>$id]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();jsonResponse(['success'=>false,'message'=>'ساخت گروه ناموفق بود.'],500);}
